    WorldBossEntityMgr:RequestWorldBossHome(function(playerRank)
        self.playerRank = playerRank
        WorldBossEntityMgr:RequestWorldBossHurtRankList(function(playerRank2)
            if isNull(self.playerRank) then
                self.playerRank = playerRank2
