--region private
function UIWorldBossPlayerRankingsBehaviour:RefreshUI()
    local count = table.count(checkTable(self._rankInfoList))
    if count <= 0 then
        CfUtils.SetActive(self.EmptyNode, true)
        return
    end
    if not self.LoopView.IsListViewInit then
        self.LoopView:InitListView(count, Bind(self, self.InitCellItem))
        self.LoopView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.LoopView, count)
    end

    if isNotNull(self.playerRank) then
        self:RefreshMeRank()
    end
end
--endregion private

