function UIWorldBossPlayerRankingsBehaviour:InitCellItem(view, index)
    local luaIndex = index + 1
    local cellData = self._rankInfoList[luaIndex]
    local cell = view:NewListViewItem("Cell")
    ---@type UIWorldBossPlayerRankNode
    local scr = CfUtils.GetLuaScr(cell, nodeScrPath)
    scr:Refresh(cellData, false, Vector3(0.3, 0.3, 1))
    scr:RefreshBg(luaIndex % 2 ~= 0)
    if luaIndex <= view.DisplayItemCount then
        CfUtils.PlayDelayShowAnimation(cell, index)
    end
    return cell
end

function UIWorldBossPlayerRankingsBehaviour:OnEventTriggerHurtRankHandler(rankInfoDojoList, percentageRank)
    Events.Broadcast(Constants.EventNames.EVENT_WORLD_BOSS_RANK_REQ_END)
    local count = table.count(rankInfoDojoList)
    if count<=0 then
        CfUtils.SetActive(self.EmptyNode, true)
        return
    end
    self._rankInfoList = rankInfoDojoList
    self.percentageRank = percentageRank
    self:RefreshUI()
end
